from z3 import *
from collections import deque
n=26
pairs=[]; var={}
for i in range(n):
 for j in range(i+1,n):
  d=min(j-i,n-(j-i))
  if d>=6:
   var[(i,j)]=Bool('m_%d_%d'%(i,j))
   pairs.append((i,j))
print('candidates',len(pairs))
s=Solver()
for v in range(n):
 inc=[var[(i,j)] for (i,j) in pairs if i==v or j==v]
 s.add(PbEq([(x,1) for x in inc],1))

def girth_and_cycle(edges):
 adj=[set() for _ in range(n)]
 for u,v in edges:
  adj[u].add(v); adj[v].add(u)
 best=10**9; bestcyc=None
 for u,v in edges:
  prev=[-1]*n; dist=[-1]*n
  q=deque([u]); dist[u]=0
  while q:
   a=q.popleft()
   if a==v: break
   for b in adj[a]:
    if (a==u and b==v) or (a==v and b==u):
     continue
    if dist[b]<0:
     dist[b]=dist[a]+1; prev[b]=a; q.append(b)
  if dist[v]>=0 and dist[v]+1<best:
   best=dist[v]+1
   path=[]; x=v
   while x!=-1:
    path.append(x)
    if x==u: break
    x=prev[x]
   path=path[::-1]
   bestcyc=path+[u]
 return (None if best==10**9 else best), bestcyc

iters=0
while True:
 iters+=1
 res=s.check()
 print('iter',iters,res,'constraints',len(s.assertions()))
 if res!=sat:
