 model=s.model()
 match=[]
 for p,x in var.items():
  if is_true(model.evaluate(x, model_completion=True)):
   match.append(p)
 edges=[]
 for i in range(n):
  u=i; v=(i+1)%n
  edges.append((min(u,v),max(u,v)))
 edges+=match
 g,cyc=girth_and_cycle(edges)
