from collections import deque

def gen_petersen(n,k):
 edges=[]
 # outer 0..n-1, inner n..2n-1
 for i in range(n):
  edges.append((min(i,(i+1)%n), max(i,(i+1)%n)))
  edges.append((min(n+i,n+((i+k)%n)), max(n+i,n+((i+k)%n))))
  edges.append((min(i,n+i), max(i,n+i)))
 return sorted(set(edges))

def girth(N,edges):
 adj=[set() for _ in range(N)]
 for u,v in edges: adj[u].add(v); adj[v].add(u)
 best=999; cyc=None
 for u,v in edges:
  dist=[-1]*N; prev=[-1]*N; q=deque([u]); dist[u]=0
  while q:
   x=q.popleft()
   for y in adj[x]:
    if (x==u and y==v) or (x==v and y==u): continue
    if dist[y]<0:
     dist[y]=dist[x]+1; prev[y]=x; q.append(y)
  if dist[v]>=0 and dist[v]+1<best:
   best=dist[v]+1
   path=[]; x=v
   while x!=-1:
    path.append(x)
    if x==u: break
    x=prev[x]
   cyc=path[::-1]+[u]
 return best,cyc
